package com.bank.watchlist.model;

import jakarta.persistence.*;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.List;

@Entity
@Table(name = "watchlists")
public class Watchlist {

    @Id
    @Column(name = "watchlist_id")
    private String watchlistId;

    @Column(name = "account_id", nullable = false)
    private String accountId;

    @Column(nullable = false)
    private String name;

    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "watchlist_symbols", joinColumns = @JoinColumn(name = "watchlist_id"))
    @Column(name = "symbol")
    private List<String> symbols = new ArrayList<>();

    @Column(name = "created_at")
    private LocalDateTime createdAt;

    @Column(name = "updated_at")
    private LocalDateTime updatedAt;

    protected Watchlist() {}

    public Watchlist(String watchlistId, String accountId, String name) {
        this.watchlistId = watchlistId;
        this.accountId = accountId;
        this.name = name;
        this.createdAt = LocalDateTime.now();
        this.updatedAt = LocalDateTime.now();
    }

    public void addSymbol(String symbol) {
        if (!symbols.contains(symbol)) {
            symbols.add(symbol);
            updatedAt = LocalDateTime.now();
        }
    }

    public boolean removeSymbol(String symbol) {
        boolean removed = symbols.remove(symbol);
        if (removed) updatedAt = LocalDateTime.now();
        return removed;
    }

    public String getWatchlistId() { return watchlistId; }
    public String getAccountId() { return accountId; }
    public String getName() { return name; }
    public List<String> getSymbols() { return symbols; }
    public LocalDateTime getCreatedAt() { return createdAt; }
    public LocalDateTime getUpdatedAt() { return updatedAt; }
}
