package com.bank.watchlist.service;

import com.bank.watchlist.dto.*;
import com.bank.watchlist.exception.WatchlistNotFoundException;
import com.bank.watchlist.model.Watchlist;
import com.bank.watchlist.repository.WatchlistRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.List;
import java.util.UUID;

@Service
@RequiredArgsConstructor
@Slf4j
public class WatchlistService {

    private final WatchlistRepository watchlistRepo;

    @Transactional
    public WatchlistResponse create(CreateWatchlistRequest request) {
        String id = "WL-" + UUID.randomUUID().toString().substring(0, 6).toUpperCase();
        Watchlist wl = new Watchlist(id, request.accountId(), request.name());
        if (request.symbols() != null) {
            request.symbols().forEach(wl::addSymbol);
        }
        watchlistRepo.save(wl);
        log.info("Created watchlist {} for account {}", id, request.accountId());
        return WatchlistResponse.from(wl);
    }

    public WatchlistResponse getById(String watchlistId) {
        return WatchlistResponse.from(findOrThrow(watchlistId));
    }

    public List<WatchlistResponse> getByAccount(String accountId) {
        return watchlistRepo.findByAccountId(accountId).stream()
            .map(WatchlistResponse::from).toList();
    }

    public List<WatchlistResponse> searchByName(String name) {
        return watchlistRepo.findByNameContainingIgnoreCase(name).stream()
            .map(WatchlistResponse::from).toList();
    }

    @Transactional
    public WatchlistResponse addSymbol(String watchlistId, String symbol) {
        Watchlist wl = findOrThrow(watchlistId);
        wl.addSymbol(symbol);
        watchlistRepo.save(wl);
        log.info("Added {} to watchlist {}", symbol, watchlistId);
        return WatchlistResponse.from(wl);
    }

    @Transactional
    public WatchlistResponse removeSymbol(String watchlistId, String symbol) {
        Watchlist wl = findOrThrow(watchlistId);
        wl.removeSymbol(symbol);
        watchlistRepo.save(wl);
        log.info("Removed {} from watchlist {}", symbol, watchlistId);
        return WatchlistResponse.from(wl);
    }

    @Transactional
    public void delete(String watchlistId) {
        if (!watchlistRepo.existsById(watchlistId)) {
            throw new WatchlistNotFoundException(watchlistId);
        }
        watchlistRepo.deleteById(watchlistId);
        log.info("Deleted watchlist {}", watchlistId);
    }

    private Watchlist findOrThrow(String id) {
        return watchlistRepo.findById(id)
            .orElseThrow(() -> new WatchlistNotFoundException(id));
    }
}
