//               @PathVariable, @RequestParam, @RequestBody, @Valid, @ResponseStatus
package com.bank.watchlist.controller;

import com.bank.watchlist.dto.*;
import com.bank.watchlist.service.WatchlistService;
import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.*;
import java.util.List;

@RestController                              // = @Controller + @ResponseBody (returns JSON)
@RequestMapping("/api/v1/watchlists")        // base path for all methods
@RequiredArgsConstructor
public class WatchlistController {

    private final WatchlistService watchlistService;

    // ─── POST: Create (JSON body → @RequestBody + @Valid) ───
    @PostMapping                              // POST /api/v1/watchlists
    @ResponseStatus(HttpStatus.CREATED)       // 201 instead of default 200
    public WatchlistResponse create(
            @RequestBody @Valid CreateWatchlistRequest request) {
        // @RequestBody: Jackson deserializes JSON → CreateWatchlistRequest record
        // @Valid: Bean Validation checks @NotBlank, @Size
        // If validation fails: MethodArgumentNotValidException → 400
        return watchlistService.create(request);
    }

    // ─── GET by ID (URL path → @PathVariable) ───
    @GetMapping("/{watchlistId}")             // GET /api/v1/watchlists/WL-001
    public WatchlistResponse getById(
            @PathVariable String watchlistId) {
        // @PathVariable: extracts "WL-001" from the URL path
        return watchlistService.getById(watchlistId);
    }

    // ─── GET by account (query string → @RequestParam) ───
    @GetMapping(params = "accountId")         // GET /api/v1/watchlists?accountId=SAV2001
    public List<WatchlistResponse> getByAccount(
            @RequestParam String accountId) {
        // @RequestParam: extracts "SAV2001" from query string
        return watchlistService.getByAccount(accountId);
    }

    // ─── GET search by name (query string → @RequestParam with default) ───
    @GetMapping("/search")                    // GET /api/v1/watchlists/search?name=banking
    public List<WatchlistResponse> search(
            @RequestParam(defaultValue = "") String name) {
        // @RequestParam with defaultValue: returns "" if param not provided
        return watchlistService.searchByName(name);
    }

    // ─── PUT: Add symbol (path variable + JSON body) ───
    @PutMapping("/{watchlistId}/symbols")     // PUT /api/v1/watchlists/WL-001/symbols
    public WatchlistResponse addSymbol(
            @PathVariable String watchlistId,
            @RequestBody @Valid AddSymbolRequest request) {
        // Both @PathVariable (from URL) and @RequestBody (from JSON) in same method
        return watchlistService.addSymbol(watchlistId, request.symbol());
    }

    // ─── DELETE: Remove symbol (two path variables) ───
    @DeleteMapping("/{watchlistId}/symbols/{symbol}")
    public WatchlistResponse removeSymbol(
            @PathVariable String watchlistId,
            @PathVariable String symbol) {
        // Two @PathVariable extractions from: /WL-001/symbols/HDFC
        return watchlistService.removeSymbol(watchlistId, symbol);
    }

    // ─── DELETE: Delete entire watchlist ───
    @DeleteMapping("/{watchlistId}")          // DELETE /api/v1/watchlists/WL-001
    @ResponseStatus(HttpStatus.NO_CONTENT)    // 204 — no body
    public void delete(@PathVariable String watchlistId) {
        watchlistService.delete(watchlistId);
    }
}
